import {
  Button,
  Flex,
  SegmentedControlRoot,
  SegmentedControlItem,
  TextField,
  useToast
} from '@bichon/ds';
import { createFileRoute, Navigate, useNavigate } from '@tanstack/react-router';
import { z } from 'zod';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { useState, useEffect, useCallback } from 'react';
import { Info } from 'lucide-react';
import i18n from '@/i18n';
import {
  getAIReviewerTotalLimit,
  getIdeaModeValidationMessage,
  getTextLength,
  MAX_IDEA_MODE_LENGTH,
  detailInputPageFormSchema,
  type DetailInputPageForm
} from '@/schema/main/detailInput';
import {
  DETAIL_INPUT_FIELDS,
  getDetailInputTotalLength
} from '@/constants/detailInput.constant';
import { StyledFunnelContentWrapper } from '@/routes/_authenticated/f/-route.style';
import {
  readFillFunnelContext,
  upsertFillFunnelContext
} from '@/routes/_authenticated/f/-funnelStorage';
import AIReviewerMode from '@/routes/_authenticated/f/prompt/-components/AIReviewerMode/AIReviewerMode';
import {
  StyledStepHeader,
  StyledTemplateName,
  StyledStepSubtitle,
  StyledInfoBanner,
  StyledToggleWrapper,
  StyledPromptFooter
} from '@/routes/_authenticated/f/prompt/-prompt.style';

type PromptMode = 'idea' | 'aiReviewer';

const DEFAULT_DETAIL_INPUT: DetailInputPageForm = {
  problem: '',
  solution: '',
  target: '',
  competitor: '',
  market: '',
  traction: '',
  strategy: '',
  businessModel: '',
  milestone: '',
  financialPlan: '',
  teamAndVision: ''
};

const savedPromptFormDataSchema = z
  .object({
    mode: z.enum(['idea', 'aiReviewer']).optional(),
    prompt: z.string().optional(),
    detailInput: detailInputPageFormSchema.optional()
  })
  .passthrough();

function getSavedPromptData(productFileId: string) {
  const formData = readFillFunnelContext({ productFileId })?.formData;

  if (!formData) {
    return null;
  }

  const result = savedPromptFormDataSchema.safeParse(formData);

  return result.success ? result.data : null;
}

function detailInputToPrompt(values: DetailInputPageForm): string {
  return DETAIL_INPUT_FIELDS.map(({ name, label }) => {
    const value = values[name]?.trim();
    if (!value) return null;
    return `${label}\n${value}`;
  })
    .filter(Boolean)
    .join('\n\n');
}

export const Route = createFileRoute('/_authenticated/f/prompt/$productFileId')(
  {
    component: RouteComponent,
    validateSearch: z.object({
      fileName: z.string().optional()
    })
  }
);

function RouteComponent() {
  const { productFileId } = Route.useParams();
  const { fileName } = Route.useSearch();
  const navigate = useNavigate();
  const toast = useToast();
  const savedData = getSavedPromptData(productFileId);
  const [mode, setMode] = useState<PromptMode>(() => savedData?.mode ?? 'idea');
  const [ideaPrompt, setIdeaPrompt] = useState<string>(
    () => savedData?.prompt ?? ''
  );

  const detailForm = useForm<DetailInputPageForm>({
    resolver: zodResolver(detailInputPageFormSchema),
    defaultValues: savedData?.detailInput ?? DEFAULT_DETAIL_INPUT
  });

  const detailValues = detailForm.watch();

  const saveToSession = useCallback(() => {
    const existingFormData =
      readFillFunnelContext({ productFileId })?.formData ?? {};

    upsertFillFunnelContext({
      step: 'prompt',
      productFileId,
      patch: {
        fileName,
        formData: {
          ...existingFormData,
          mode,
          prompt: ideaPrompt,
          detailInput: detailValues
        }
      }
    });
  }, [productFileId, fileName, mode, ideaPrompt, detailValues]);

  useEffect(() => {
    saveToSession();
  }, [saveToSession]);

  const getResolvedPrompt = (): string => {
    if (mode === 'idea') return ideaPrompt.trim();
    return detailInputToPrompt(detailValues);
  };

  const handleNext = () => {
    const prompt = getResolvedPrompt();
    if (mode === 'idea') {
      if (getTextLength(ideaPrompt) > MAX_IDEA_MODE_LENGTH) {
        toast.showToast(getIdeaModeValidationMessage(), {
          duration: 3000
        });
        return;
      }
    } else {
      const aiReviewerTotalLimit = getAIReviewerTotalLimit(
        DETAIL_INPUT_FIELDS.length
      );
      const aiReviewerTotalLength = getDetailInputTotalLength(detailValues);

      if (aiReviewerTotalLength > aiReviewerTotalLimit) {
        toast.showToast(
          i18n.t('common:form.validation.maximumLengthAiReviewerTotal', {
            count: aiReviewerTotalLimit
          }),
          { duration: 3000 }
        );
        return;
      }
    }

    const existingFormData =
      readFillFunnelContext({ productFileId })?.formData ?? {};

    upsertFillFunnelContext({
      step: 'prompt',
      productFileId,
      patch: {
        fileName,
        formData: {
          ...existingFormData,
          mode,
          prompt: mode === 'idea' ? ideaPrompt : prompt,
          detailInput: detailValues,
          resolvedPrompt: prompt
        }
      }
    });

    navigate({
      to: '/f/upload/$productFileId',
      params: { productFileId },
      search: fileName ? { fileName } : undefined
    });
  };

  const handleSkip = () => {
    const existingFormData =
      readFillFunnelContext({ productFileId })?.formData ?? {};

    upsertFillFunnelContext({
      step: 'prompt',
      productFileId,
      patch: {
        fileName,
        formData: {
          ...existingFormData,
          mode,
          prompt: '',
          detailInput: DEFAULT_DETAIL_INPUT,
          resolvedPrompt: ''
        }
      }
    });

    navigate({
      to: '/f/upload/$productFileId',
      params: { productFileId },
      search: fileName ? { fileName } : undefined
    });
  };

  if (!productFileId) {
    return <Navigate to="/f/template" />;
  }

  const hasContent =
    mode === 'idea'
      ? ideaPrompt.trim().length > 0
      : Object.values(detailValues).some(
          (value) => value != null && value.trim().length > 0
        );

  return (
    <Flex
      direction="column"
      width="100%"
      style={{ minHeight: '0px', flex: 1 }}
    >
      <StyledFunnelContentWrapper>
        <StyledStepHeader>
          {fileName && (
            <StyledTemplateName>&apos;{fileName}&apos;</StyledTemplateName>
          )}
          <StyledStepSubtitle>
            문서 작성을 위한 프롬프트를 입력해주세요
          </StyledStepSubtitle>
        </StyledStepHeader>

        <StyledInfoBanner>
          <Info size={16} />
          <span>
            사업아이템 설명을 자유롭게 입력하거나, AI 심사역과 함께
            고도화하는 단계입니다. 단계를 건너뛸 수 있습니다.
          </span>
        </StyledInfoBanner>

        <StyledToggleWrapper>
          <SegmentedControlRoot
            value={mode}
            onValueChange={(value) => {
              if (value) setMode(value as PromptMode);
            }}
          >
            <SegmentedControlItem value="idea">
              아이디어 모드
            </SegmentedControlItem>
            <SegmentedControlItem value="aiReviewer">
              AI 심사역과 함께
            </SegmentedControlItem>
          </SegmentedControlRoot>
        </StyledToggleWrapper>

        {mode === 'idea' ? (
          <TextField
            multiline
            minRows={12}
            placeholder="자유롭게 아이템 내용을 입력할 수 있습니다. 프롬프트 작성이 막막하다면 'AI 심사역과 함께' 진행해보세요."
            maxLength={MAX_IDEA_MODE_LENGTH}
            width="100%"
            value={ideaPrompt}
            onChange={(eventOrValue) => {
              const value =
                typeof eventOrValue === 'string'
                  ? eventOrValue
                  : ((
                      eventOrValue?.target as
                        | HTMLTextAreaElement
                        | HTMLInputElement
                        | undefined
                    )?.value ?? '');
              setIdeaPrompt(value);
            }}
          />
        ) : (
          <AIReviewerMode form={detailForm} />
        )}
      </StyledFunnelContentWrapper>

      <StyledPromptFooter>
        <Button
          type="button"
          variant="outlined"
          size="large"
          onClick={() => navigate({ to: '/f/template' })}
        >
          이전
        </Button>
        <Flex gap={12} style={{ marginLeft: 'auto' }}>
          <Button
            type="button"
            variant="outlined"
            size="large"
            onClick={handleSkip}
          >
            건너뛰기
          </Button>
          <Button
            type="button"
            variant="filled"
            size="large"
            onClick={handleNext}
            disabled={!hasContent}
          >
            다음 단계
          </Button>
        </Flex>
      </StyledPromptFooter>
    </Flex>
  );
}
